/** Нержавеющая лента (штрипс х/к) — отдельный источник данных.
 *
 * Собрана из двух каталогов (import/lenta-export*.json) с разделением по
 * происхождению — origin='import' (zel) и origin='rf' (sin):
 * • Импорт — поверхности AISI/EN: 2B (полуматовая), BA (зеркальная),
 *   4N (шлифованная); 2BA объединён с BA; PE вынесен в флаг film. Марка
 *   «AISI (кир.)», ГОСТ не проставляем (импорт не под ГОСТ 4986).
 * • РФ — поверхности русскими терминами: «Обычная» (матовая),
 *   «Блестящая» (зеркальная). Марка «кир. (AISI)», ГОСТ 4986-79.
 *
 * Цена (руб/кг ×1000 = ₽/т): импорт добирает цену из sin для того же SKU,
 * РФ — своя цена sin. film=true (бывш. PE) — surface пустой, «(с плёнкой)».
 *
 * Сгенерировано scripts/_lenta_build.py. Позиций: 644 (импорт 518, РФ 126), марок: 23.
 */

export interface LentaSku {
	hub: 'lenta';
	/** Происхождение: импортная (AISI-поверхности) или российская лента. */
	origin: 'import' | 'rf';
	sub: string;
	grade: string;
	roll: string | null;
	alloy: string | null;
	surface: string;
	/** Защитная плёнка (бывш. поверхность PE) — базовая отделка не указана. */
	film: boolean;
	/** Толщина, мм — строка с запятой (единообразно с pricelist). */
	size: string;
	/** Ширина, мм (200 | 400). */
	width: number;
	/** Толщина, мм — число (для фильтра/карточки). */
	thickness: number;
	/** Ширина как строка — читается PriceTable через поле format ('Ширина'). */
	format: string;
	unit: string;
	price: number | null;
	priceUnit: number | null;
	slug: string;
	dlina: string | null;
	fact: string | null;
	ostatok: number | null;
	gost: string;
	name: string;
}

